import { SegmentedControl } from '@kerfjs/ui/segmented-control';
import '@kerfjs/ui/layout.css';

export type WorkspaceView = 'board' | 'list' | 'timeline';
export type WorkspaceAction = { type: 'workspace/view-changed'; view: WorkspaceView };
const options = [{ value: 'board', label: 'Board' }, { value: 'list', label: 'List' }, { value: 'timeline', label: 'Timeline' }] as const;

// The application's reducer owns the selected view; this adapter sends a stable action.
export function WorkspaceViewChoice({ value, dispatch }: {
  value: WorkspaceView; dispatch: (action: WorkspaceAction) => void;
}) {
  return <SegmentedControl aria-label="Workspace view" value={value} options={options}
    onChange={(next: string) => {
      if (options.some(option => option.value === next) && next !== value)
        dispatch({ type: 'workspace/view-changed', view: next as WorkspaceView });
    }} />;
}
